<section class="portal-metrics"><article><small>Total contribuído</small><b>R$ <?= number_format($totalPago,2,',','.') ?></b><span>✓ &nbsp;<?= count(array_filter($parcelasAtuais,fn($p)=>(float)$p['pago']+0.001>=(float)$p['valor'])) ?> parcelas quitadas</span></article><article><small>Próximo vencimento</small><b><?= $proxima?date('d M. Y',strtotime($proxima['vencimento'])):'Sem parcelas' ?></b><span>▦ &nbsp;Mensalidade de R$ <?= number_format((float)($proxima['valor']??0),2,',','.') ?></span></article><article><small>Situação atual</small><b class="on-track"><?= $proxima&&strtotime($proxima['vencimento'])<strtotime('today')?'Pendente':'Em dia' ?></b><span><?= $proxima&&strtotime($proxima['vencimento'])<strtotime('today')?'• Parcela vencida':'✓ &nbsp;Nenhuma pendência' ?></span></article></section>
<section class="portal-plan-row"><article class="panel portal-plan"><div class="portal-section-head"><div><h2>Plano de contribuição</h2><p>Mensal · <?= count($parcelasAtuais) ?> parcelas previstas</p></div><span class="status-pill up-to-date">ATIVO</span></div><?php $qtdPagas=count(array_filter($parcelasAtuais,fn($p)=>(float)$p['pago']+0.001>=(float)$p['valor']));$pct=count($parcelasAtuais)?(int)round($qtdPagas/count($parcelasAtuais)*100):0 ?><div class="plan-progress-head"><span><?= $qtdPagas ?> de <?= count($parcelasAtuais) ?> parcelas</span><b><?= $pct ?>% concluído</b></div><div class="plan-progress"><i style="width:<?= $pct ?>%"></i></div><?php if($proxima):?><div class="next-due"><div class="due-date"><b><?= mb_strtoupper(date('M',strtotime($proxima['vencimento']))) ?></b><strong><?= date('d',strtotime($proxima['vencimento'])) ?></strong></div><div><small>Próxima parcela</small><b>R$ <?= number_format((float)$proxima['valor'],2,',','.') ?></b><small>Competência <?= date('m/Y',strtotime($proxima['competencia'])) ?></small></div><span class="due-status">A vencer</span></div><?php endif?></article><article class="collective-goal"><small>META COLETIVA</small><h3>Juntos, a turma já chegou a</h3><?php $resumoParticipante=$financeiro->resumo((int)$coorteAtual['id']);$meta=(float)$coorteAtual['meta'];$percentualMeta=$meta>0?min(100,(int)round($resumoParticipante['receitas']/$meta*100)):0 ?><strong><?= $percentualMeta ?>%</strong><div class="collective-progress"><i style="width:<?= $percentualMeta ?>%"></i></div><p>Faltam R$ <?= number_format(max(0,$meta-$resumoParticipante['receitas']),2,',','.') ?> para a meta da formatura.</p></article></section>
<section class="panel portal-history"><div class="portal-section-head"><div><h2>Meu histórico de pagamentos</h2><p>Somente contribuições associadas ao seu cadastro</p></div><button id="download-statement">⇩ &nbsp; Baixar extrato</button></div><div class="table-scroll"><table class="ledger-table" id="payment-table"><thead><tr><th>DESCRIÇÃO</th><th>CATEGORIA</th><th>DATA</th><th>MEIO</th><th>VALOR</th></tr></thead><tbody><?php foreach($pagamentos as [$descricao,$pessoa,$categoria,$data,$meio,$valor]): ?><tr><td><span class="row-icon green">↙</span><span><b><?= e($descricao) ?></b><small><?= e($pessoa) ?></small></span></td><td><label class="tag"><?= e($categoria) ?></label></td><td><?= e($data) ?></td><td><?= e($meio) ?></td><td class="money-in"><?= e($valor) ?></td></tr><?php endforeach ?></tbody></table></div></section>
</main><script>document.querySelector('.icon-button').addEventListener('click',()=>alert('Você está em dia com as notificações.'));document.getElementById('download-statement').addEventListener('click',()=>{const rows=[...document.querySelectorAll('#payment-table tr')].map(r=>[...r.cells].map(c=>'"'+c.innerText.replace(/\s+/g,' ').trim().replaceAll('"','""')+'"').join(';'));const blob=new Blob(['\ufeff'+rows.join('\r\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='meu-extrato-formapay.csv';a.click();URL.revokeObjectURL(a.href)});</script></body></html>



